using MarathonRMS.DTOs.Events;using MarathonRMS.WebApp.ApiClients;using MarathonRMS.WebApp.Infrastructure;using Microsoft.AspNetCore.Mvc;
namespace MarathonRMS.WebApp.Pages.Organizer.Events;
public class LifecycleModel:BasePageModel
{private readonly EventApiClient _api;public LifecycleModel(EventApiClient api)=>_api=api;[BindProperty(SupportsGet=true)]public int Id{get;set;}[BindProperty]public DateOnly NewEventDate{get;set;}[BindProperty]public string Reason{get;set;}="";public EventDetailDto? Event{get;private set;}public EventPolicyDto? Policy{get;private set;}public async Task<IActionResult> OnGetAsync(CancellationToken ct)=>await Load(ct);public async Task<IActionResult> OnPostPostponeAsync(CancellationToken ct){try{await _api.PostponeAsync(Id,new(){NewEventDate=NewEventDate},ct);StatusMessage="Đã hoãn giải và dời các mốc thời gian.";return RedirectToPage("Index");}catch(ApiException ex){return await HandleApiErrorAsync(ex)??await Load(ct);}}public async Task<IActionResult> OnPostCancelAsync(CancellationToken ct){try{Policy=await _api.GetPolicyAsync(Id,ct);await _api.CancelAsync(Id,new(){Reason=Reason,RefundOption=Policy.ForceMajeurePolicy},ct);StatusMessage="Đã hủy giải và áp dụng chính sách bất khả kháng.";return RedirectToPage("Index");}catch(ApiException ex){return await HandleApiErrorAsync(ex)??await Load(ct);}}private async Task<IActionResult> Load(CancellationToken ct){try{Event=await _api.GetAsync(Id,ct);Policy=await _api.GetPolicyAsync(Id,ct);NewEventDate=Event.EventDate.AddDays(7);}catch(ApiException ex){return await HandleApiErrorAsync(ex)??Page();}return Page();}}
